mapper.select:
SELECT m.*
FROM oauthAccount oa
         JOIN member m ON oa.memberId = m.id
WHERE oa.oauthId = #{oauthId}
  AND oa.provider = #{provider}

mapper.update:
UPDATE member
SET emailVerificationToken = #{token},
    emailVerificationExpiry = #{expiry}
WHERE id = #{memberId}

UPDATE member
SET resetToken = #{token},
    resetTokenExpiry = #{expiry}
WHERE id = #{memberId}

UPDATE `member`
loginId = #{loginId}, loginPw = #{loginPw}, `name` = #{name}, nickName = #{nickName}, email = #{email},
WHERE id = #{loginedMemberId}

UPDATE member
SET nickName = #{nickName}
WHERE id = #{memberId}

UPDATE member
SET introduce = #{introduce}
WHERE id = #{memberId}

UPDATE member
SET profileUrl = #{profileUrl}
WHERE id = #{memberId}

mapper.select:
SELECT id, nickName, email, fcmToken
FROM member
WHERE id = #{memberId}

mapper.update:
UPDATE member
SET fcmToken = #{fcmToken}
WHERE id = #{memberId}

UPDATE member
SET fcmToken = #{token}
WHERE id = #{memberId}

mapper.delete:
DELETE FROM follow
WHERE toMemberId = #{toMemberId}
  AND fromMemberId = #{fromMemberId}
